//! Experimental fd-to-fd export. The child is single-threaded and never changes the parent's cwd.
use std::{ffi::{CStr,CString,OsStr},fs,io::{self,Read,Seek,Write},os::{fd::{AsRawFd,FromRawFd},unix::{ffi::OsStrExt,process::CommandExt}},path::Path,process::{Command,Stdio}};
use serde_json::{json,Value};use sha2::{Digest,Sha256};
type R<T>=Result<T,Box<dyn std::error::Error>>;
fn name(n:&OsStr)->R<CString>{Ok(CString::new(n.as_bytes())?)}
fn openat(dir:&fs::File,n:&OsStr,flags:i32,mode:u32)->R<fs::File>{let name=name(n)?;let fd=unsafe{libc::openat(dir.as_raw_fd(),name.as_ptr(),flags|libc::O_CLOEXEC|libc::O_NOFOLLOW,mode)};if fd<0{return Err(io::Error::last_os_error().into())}Ok(unsafe{fs::File::from_raw_fd(fd)})}
fn mkdirat(dir:&fs::File,n:&OsStr)->R<fs::File>{let name=name(n)?;if unsafe{libc::mkdirat(dir.as_raw_fd(),name.as_ptr(),0o700)}!=0{return Err(io::Error::last_os_error().into())}openat(dir,n,libc::O_RDONLY|libc::O_DIRECTORY,0)}
fn entries(dir:&fs::File)->R<Vec<std::ffi::OsString>>{struct Stream(*mut libc::DIR);impl Drop for Stream{fn drop(&mut self){unsafe{libc::closedir(self.0);}}}let duplicate=unsafe{libc::dup(dir.as_raw_fd())};if duplicate<0{return Err(io::Error::last_os_error().into())}let raw=unsafe{libc::fdopendir(duplicate)};if raw.is_null(){unsafe{libc::close(duplicate)};return Err(io::Error::last_os_error().into())}let stream=Stream(raw);let mut result=Vec::new();loop{#[cfg(target_os="macos")] unsafe{*libc::__error()=0};#[cfg(target_os="linux")] unsafe{*libc::__errno_location()=0};let entry=unsafe{libc::readdir(stream.0)};if entry.is_null(){let e=io::Error::last_os_error();if e.raw_os_error().unwrap_or(0)!=0{return Err(e.into())}break}let s=unsafe{CStr::from_ptr((*entry).d_name.as_ptr())}.to_bytes();if s!=b"."&&s!=b".."{result.push(OsStr::from_bytes(s).to_owned())}}result.sort();Ok(result)}
fn copy_file(mut input:fs::File,dest:&fs::File,n:&OsStr)->R<()> {use std::os::unix::fs::MetadataExt;let before=input.metadata()?;if !before.is_file(){return Err("invalid source file".into())}let mut out=openat(dest,n,libc::O_RDWR|libc::O_CREAT|libc::O_EXCL,0o600)?;let mut h=Sha256::new();let mut buf=[0u8;65536];loop{let count=input.read(&mut buf)?;if count==0{break}out.write_all(&buf[..count])?;h.update(&buf[..count]);}out.sync_all()?;out.rewind()?;let mut check=Sha256::new();loop{let count=out.read(&mut buf)?;if count==0{break}check.update(&buf[..count]);}let after=input.metadata()?;let identity=|m:&fs::Metadata|(m.dev(),m.ino(),m.len(),m.mtime(),m.mtime_nsec(),m.ctime(),m.ctime_nsec());if h.finalize()!=check.finalize()||identity(&before)!=identity(&after){return Err("source changed or copy verification failed".into())}Ok(())}
fn copy_children(source:&fs::File,dest:&fs::File,root:bool)->R<()> {for entry in entries(source)?{let text=entry.to_string_lossy();if root&&(matches!(text.as_ref(),".atlas-operation.lock"|".atlas-session.lock"|".atlas-workspace-id"|"atlas.sqlite3-shm"|"atlas.sqlite3-journal"|".atlas-semantic-native"|".atlas-worker-index")||text.starts_with(".atlas-upload-")||text.starts_with(".atlas-worker-upload-")){continue}let file=openat(source,&entry,libc::O_RDONLY|libc::O_NONBLOCK,0)?;let meta=file.metadata()?;if meta.is_dir(){let target=mkdirat(dest,&entry)?;copy_children(&file,&target,false)?;target.sync_all()?}else if meta.is_file(){copy_file(file,dest,&entry)?}else{return Err("unsupported source entry".into())}}Ok(())}
fn copy_index(source:&fs::File,dest:&fs::File,index_name:&str)->R<()> {let root=match openat(source,OsStr::new(index_name),libc::O_RDONLY|libc::O_DIRECTORY,0){Ok(v)=>v,Err(e) if e.downcast_ref::<io::Error>().is_some_and(|e|e.kind()==io::ErrorKind::NotFound)=>return Ok(()),Err(e)=>return Err(e)};let mut current=match openat(&root,OsStr::new("current"),libc::O_RDONLY|libc::O_NONBLOCK,0){Ok(v)=>v,Err(e) if e.downcast_ref::<io::Error>().is_some_and(|e|e.kind()==io::ErrorKind::NotFound)=>return Ok(()),Err(e)=>return Err(e)};let mut generation=String::new();current.read_to_string(&mut generation)?;if !generation.starts_with("gen-")||!generation.chars().all(|c|c.is_ascii_alphanumeric()||c=='-'){return Err("invalid search index".into())}current.rewind()?;let gen=openat(&root,OsStr::new(&generation),libc::O_RDONLY|libc::O_DIRECTORY,0)?;let mut metadata=Vec::new();openat(&gen,OsStr::new("metadata.json"),libc::O_RDONLY|libc::O_NONBLOCK,0)?.read_to_end(&mut metadata)?;if index_name==".atlas-worker-index"{let mut expected=String::new();openat(&gen,OsStr::new("metadata.sha256"),libc::O_RDONLY|libc::O_NONBLOCK,0)?.read_to_string(&mut expected)?;if expected!=format!("{:x}",Sha256::digest(&metadata)){return Err("search metadata checksum mismatch".into())}}let metadata:Value=serde_json::from_slice(&metadata)?;let expected=metadata["index_sha256"].as_str().ok_or("invalid search index metadata")?;let mut file=openat(&gen,OsStr::new("index.faiss"),libc::O_RDONLY|libc::O_NONBLOCK,0)?;let mut hash=Sha256::new();let mut buffer=[0u8;65536];loop{let count=file.read(&mut buffer)?;if count==0{break}hash.update(&buffer[..count]);}if format!("{:x}",hash.finalize())!=expected{return Err("search index checksum mismatch".into())}let out=mkdirat(dest,OsStr::new(index_name))?;copy_file(current,&out,OsStr::new("current"))?;let genout=mkdirat(&out,OsStr::new(&generation))?;copy_children(&gen,&genout,false)?;genout.sync_all()?;out.sync_all()?;Ok(())}
pub fn inside(dest:&fs::File,source:&fs::File)->R<bool>{use std::os::unix::fs::MetadataExt;let src=source.metadata()?;let mut cur=dest.try_clone()?;loop{let meta=cur.metadata()?;if(meta.dev(),meta.ino())==(src.dev(),src.ino()){return Ok(true)}let parent=openat(&cur,OsStr::new(".."),libc::O_RDONLY|libc::O_DIRECTORY,0)?;let pm=parent.metadata()?;if(pm.dev(),pm.ino())==(meta.dev(),meta.ino()){return Ok(false)}cur=parent}}
fn make_id(dest:&fs::File)->R<()>{let mut file=openat(dest,OsStr::new(".atlas-workspace-id"),libc::O_WRONLY|libc::O_CREAT|libc::O_EXCL,0o600)?;file.write_all(uuid::Uuid::new_v4().simple().to_string().as_bytes())?;file.sync_all()?;Ok(())}
pub fn run(destination:&fs::File,sources:&[fs::File],pinned:&[fs::File],names:&[String],protected:&[bool],passwords:&[String],before_publish:impl FnOnce()->Result<(),String>)->R<(u16,Value)>{let (mut control,child_control)=std::os::unix::net::UnixStream::pair()?;let control_fd=child_control.as_raw_fd();let fds:Vec<i32>=std::iter::once(destination).chain(sources.iter()).chain(pinned.iter()).map(AsRawFd::as_raw_fd).collect();let nonce=uuid::Uuid::new_v4().simple().to_string();let mut cmd=Command::new(std::env::current_exe()?);cmd.arg("--direct-export").arg(&nonce).arg(control_fd.to_string());for fd in &fds{cmd.arg(fd.to_string());}cmd.stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null());unsafe{cmd.pre_exec(move||{if libc::fcntl(control_fd,libc::F_SETFD,0)<0{return Err(io::Error::last_os_error())}for fd in &fds{if libc::fcntl(*fd,libc::F_SETFD,0)<0{return Err(io::Error::last_os_error())}}Ok(())});}let mut child=cmd.spawn()?;drop(child_control);child.stdin.take().ok_or("export input")?.write_all(&serde_json::to_vec(&json!({"names":names,"protected":protected,"passwords":passwords}))?)?;// A stalled child must not retain source locks forever. The deadline covers
// copying and publication, including waiting for the parent's approval.
#[cfg(feature="test-hook")] let timeout=std::env::var("ATLAS_TEST_EXPORT_TIMEOUT_MS").ok().and_then(|v|v.parse().ok()).map(std::time::Duration::from_millis).unwrap_or(std::time::Duration::from_secs(1800));
#[cfg(not(feature="test-hook"))] let timeout=std::time::Duration::from_secs(1800);
let deadline=std::time::Instant::now()+timeout;control.set_read_timeout(Some(timeout))?;control.set_write_timeout(Some(timeout))?;let mut signal=[0u8;1];match control.read_exact(&mut signal){Ok(()) if signal[0]==1=>{let approved=before_publish().is_ok();if control.write_all(&[u8::from(approved)]).is_err(){let _=child.kill();}},Ok(())=>{let _=child.kill();},Err(error) if matches!(error.kind(),io::ErrorKind::WouldBlock|io::ErrorKind::TimedOut)=>{let _=child.kill();let _=child.wait();return Err("Превышено время сохранения копии".into())},Err(_)=>{}}drop(control);loop{if child.try_wait()?.is_some(){break}if std::time::Instant::now()>=deadline{let _=child.kill();let _=child.wait();return Err("Превышено время сохранения копии".into())}std::thread::sleep(std::time::Duration::from_millis(20));}let output=child.wait_with_output()?;if !output.status.success(){return Err(format!("Экспорт прерван. Незавершённая копия может находиться в выбранной папке: .atlas-export-{nonce}").into())}let value:Value=serde_json::from_slice(&output.stdout)?;Ok((value["status"].as_u64().ok_or("invalid response")? as u16,value["body"].clone()))}
pub fn child(args:&[String])->R<()> {let mut input=String::new();std::io::stdin().read_to_string(&mut input)?;let input:Value=serde_json::from_str(&input)?;let result=execute(args,&input);let(status,body)=match result{Ok(v)=>(200,v),Err(e)=>{let message=e.to_string();if message.contains("database is locked")||message.contains("database is busy"){(409,json!({"error":format!("Пространство занято. Дождитесь завершения записи и повторите экспорт. {}",message.split_once(". Незавершённая копия").map(|(_,tail)|format!("Незавершённая копия{tail}")).unwrap_or_default())}))}else{(500,json!({"error":format!("Не удалось сохранить копию: {message}")}))}}};println!("{}",json!({"status":status,"body":body}));Ok(())}
fn execute(args:&[String],input:&Value)->R<Value>{let parent=unsafe{libc::getppid()};if parent<=1{return Err("Экспорт прерван".into())}if args.len()<5||args.len()>203||(args.len()-3)%2!=0{return Err("invalid descriptors".into())}let nonce=&args[0];if nonce.len()!=32||!nonce.chars().all(|c|c.is_ascii_hexdigit()){return Err("invalid export id".into())}let control_fd=args[1].parse::<i32>().map_err(|_|"invalid control fd")?;let mut control=unsafe{std::os::unix::net::UnixStream::from_raw_fd(control_fd)};let fds=args[2..].iter().map(|v|v.parse::<i32>().map_err(|_|"invalid fd")).collect::<Result<Vec<_>,_>>()?;let dest=unsafe{fs::File::from_raw_fd(fds[0])};let count=(fds.len()-1)/2;let sources:Vec<fs::File>=fds[1..1+count].iter().map(|fd|unsafe{fs::File::from_raw_fd(*fd)}).collect();let pinned:Vec<fs::File>=fds[1+count..].iter().map(|fd|unsafe{fs::File::from_raw_fd(*fd)}).collect();let names=input["names"].as_array().filter(|v|v.len()==sources.len()).ok_or("invalid workspace names")?;let protected=input["protected"].as_array().filter(|v|v.len()==sources.len()).ok_or("invalid workspace types")?;let passwords=input["passwords"].as_array().filter(|v|v.len()==sources.len()).ok_or("invalid passwords")?;for src in &sources{if inside(&dest,src)?{return Err("Нельзя сохранить копию внутри пространства".into())}}
 if unsafe{libc::fchdir(dest.as_raw_fd())}!=0{return Err(io::Error::last_os_error().into())}let stage=format!(".atlas-export-{nonce}");let target=format!("Atlas-{nonce}");let stagefd=mkdirat(&dest,OsStr::new(&stage))?;#[cfg(feature="test-hook")] if let Ok(path)=std::env::var("ATLAS_TEST_DIRECT_EXPORT_BARRIER"){let dir=Path::new(&path);let _=fs::write(dir.join("ready"),b"ready");let start=std::time::Instant::now();while !dir.join("resume").exists()&&start.elapsed()<std::time::Duration::from_secs(10){std::thread::sleep(std::time::Duration::from_millis(10));}}let result=(||->R<()>{for (i,src) in sources.iter().enumerate(){if protected[i].as_bool().ok_or("invalid workspace type")?{let workspace=mkdirat(&stagefd,OsStr::new(&format!("workspace-{}",i+1)))?;if unsafe{libc::fchdir(workspace.as_raw_fd())}!=0{return Err(io::Error::last_os_error().into())}let password=passwords[i].as_str().ok_or("invalid password")?;#[cfg(feature="test-hook")]let mut did_wait=false;atlas_sqlcipher_proof::Vault::snapshot_closed_pinned(src,&pinned[i],Path::new("workspace.atlas"),password,|_,_|{#[cfg(feature="test-hook")]if !did_wait{did_wait=true;if let Some(dir)=std::env::var_os("ATLAS_TEST_PROTECTED_EXPORT_BARRIER"){let dir=Path::new(&dir);let _=fs::write(dir.join("ready"),b"ready");let start=std::time::Instant::now();while !dir.join("resume").exists()&&start.elapsed()<std::time::Duration::from_secs(15){std::thread::sleep(std::time::Duration::from_millis(10));}}}}).map_err(|e|format!("Не удалось сохранить защищённое пространство: {e}"))?;let title=names[i].as_str().filter(|v|!v.trim().is_empty()&&v.chars().count()<=100).ok_or("invalid workspace name")?;let meta_bytes=serde_json::to_vec(&json!({"name":title,"protected":true}))?;for (name,data) in [(".atlas-protected",b"atlas-protected-v1".as_slice()),(".workspace.json",meta_bytes.as_slice())]{let mut f=openat(&workspace,OsStr::new(name),libc::O_WRONLY|libc::O_CREAT|libc::O_EXCL,0o600)?;f.write_all(data)?;f.sync_all()?;}workspace.sync_all()?;continue}if unsafe{libc::fchdir(src.as_raw_fd())}!=0{return Err(io::Error::last_os_error().into())}let _guard=atlas_native_storage_contract::workspace_lock(Path::new("."))?;for marker in [".atlas-protected","workspace.atlas"]{match fs::symlink_metadata(marker){Ok(_)=>return Err("Защищённое пространство пока нельзя экспортировать этим способом".into()),Err(e) if e.kind()==io::ErrorKind::NotFound=>{},Err(e)=>return Err(e.into())}}atlas_native_storage_contract::validate_database_files(Path::new("."))?;let db=rusqlite::Connection::open_with_flags("atlas.sqlite3",rusqlite::OpenFlags::SQLITE_OPEN_READ_WRITE|rusqlite::OpenFlags::SQLITE_OPEN_NOFOLLOW)?;let mode:String=db.query_row("PRAGMA locking_mode=EXCLUSIVE",[],|r|r.get(0))?;if mode!="exclusive"{return Err("Не удалось заблокировать базу".into())}db.execute_batch("BEGIN EXCLUSIVE")?;let check:String=db.query_row("PRAGMA quick_check",[],|r|r.get(0))?;if check!="ok"{return Err("База пространства повреждена".into())}let workspace=mkdirat(&stagefd,OsStr::new(&format!("workspace-{}",i+1)))?;copy_children(src,&workspace,true)?;copy_index(src,&workspace,".atlas-semantic-native")?;copy_index(src,&workspace,".atlas-worker-index")?;make_id(&workspace)?;let marker=match openat(&workspace,OsStr::new(".workspace.json"),libc::O_RDONLY,0){Ok(_)=>true,Err(e) if e.downcast_ref::<io::Error>().is_some_and(|e|e.kind()==io::ErrorKind::NotFound)=>false,Err(e)=>return Err(e)};let legacy=match openat(&workspace,OsStr::new(".atlas-workspace.json"),libc::O_RDONLY,0){Ok(_)=>true,Err(e) if e.downcast_ref::<io::Error>().is_some_and(|e|e.kind()==io::ErrorKind::NotFound)=>false,Err(e)=>return Err(e)};if !marker&&!legacy{let title=names[i].as_str().filter(|v|!v.trim().is_empty()&&v.chars().count()<=100).ok_or("invalid workspace name")?;let mut file=openat(&workspace,OsStr::new(".workspace.json"),libc::O_WRONLY|libc::O_CREAT|libc::O_EXCL,0o600)?;file.write_all(&serde_json::to_vec(&json!({"name":title}))?)?;file.sync_all()?;}workspace.sync_all()?;db.execute_batch("ROLLBACK")?;drop(db);drop(_guard);if unsafe{libc::fchdir(workspace.as_raw_fd())}!=0{return Err(io::Error::last_os_error().into())}let copy=rusqlite::Connection::open_with_flags("atlas.sqlite3",rusqlite::OpenFlags::SQLITE_OPEN_READ_WRITE|rusqlite::OpenFlags::SQLITE_OPEN_NOFOLLOW)?;let check:String=copy.query_row("PRAGMA quick_check",[],|r|r.get(0))?;if check!="ok"{return Err("Ошибка проверки скопированной базы".into())}drop(copy);openat(&workspace,OsStr::new("atlas.sqlite3"),libc::O_RDONLY,0)?.sync_all()?;workspace.sync_all()?;}
 stagefd.sync_all()?;#[cfg(feature="test-hook")] if std::env::var_os("ATLAS_TEST_DIRECT_EXPORT_SYNC_BEFORE").is_some(){return Err("injected sync failure".into())}if unsafe{libc::fchdir(dest.as_raw_fd())}!=0{return Err(io::Error::last_os_error().into())}if unsafe{libc::getppid()}!=parent{return Err("Экспорт прерван".into())}control.write_all(&[1])?;let mut approval=[0u8;1];control.read_exact(&mut approval)?;if approval[0]!=1{return Err("Источник изменился во время копирования".into())}atlas_native_storage_contract::publish_snapshot(Path::new(&stage),Path::new(&target))?;Ok(())})();if let Err(e)=result{return Err(format!("{e}. Незавершённая копия осталась в выбранной папке: {stage}").into())}#[cfg(feature="test-hook")]let injected_after=std::env::var_os("ATLAS_TEST_DIRECT_EXPORT_SYNC_AFTER").is_some();#[cfg(not(feature="test-hook"))]let injected_after=false;let warning=if injected_after||dest.sync_all().is_err(){Some("Копия создана, но не удалось подтвердить сохранение на диске.")}else{None};Ok(json!({"folder":target,"warning":warning}))}
